$f = 'D:\Nyxen\OlympiadReady\OlympiadReadySolutions\data\spell-bee\grade1_body_parts.json'
$raw = [System.IO.File]::ReadAllText($f, [System.Text.Encoding]::UTF8)
$trimmed = $raw.TrimEnd().TrimEnd(']').TrimEnd().TrimEnd(',')

$extra = @'
,
  {"questionText":"Which is the CORRECT spelling of the tiny part of the eye that controls light entry?","options":["A) pupill","B) pupil","C) puupil","D) pupiil"],"correctAnswer":"B","topic":"Body Parts and Their Functions","subTopic":"correct-spelling","difficulty":"Advanced","explanation":"'Pupil' is the correct spelling - P-U-P-I-L. The pupil is the dark centre of the eye that controls how much light enters."},
  {"questionText":"Which is the CORRECT spelling of the coloured ring around the pupil?","options":["A) irris","B) irise","C) iris","D) iries"],"correctAnswer":"C","topic":"Body Parts and Their Functions","subTopic":"correct-spelling","difficulty":"Advanced","explanation":"'Iris' is the correct spelling - I-R-I-S. The iris is the coloured part of the eye. Just 4 letters."},
  {"questionText":"Which is the CORRECT spelling of the upper arm bone?","options":["A) humerrus","B) humeros","C) humerus","D) humeris"],"correctAnswer":"C","topic":"Body Parts and Their Functions","subTopic":"correct-spelling","difficulty":"Advanced","explanation":"'Humerus' is the correct spelling - H-U-M-E-R-U-S. The humerus is the long bone in the upper arm. It ends with US."},
  {"questionText":"Which is the CORRECT spelling of the soft lower part of the outer ear?","options":["A) earlob","B) earloobe","C) earlobe","D) earlobbe"],"correctAnswer":"C","topic":"Body Parts and Their Functions","subTopic":"correct-spelling","difficulty":"Advanced","explanation":"'Earlobe' is the correct spelling - E-A-R-L-O-B-E. The earlobe is the soft, fleshy part at the bottom of the ear."},
  {"questionText":"Choose the correctly spelled word: 'The _____ pumps blood to all parts of the body.'","options":["A) haert","B) heartt","C) herat","D) heart"],"correctAnswer":"D","topic":"Body Parts and Their Functions","subTopic":"fill-blank","difficulty":"Advanced","explanation":"'Heart' is the correct spelling - H-E-A-R-T. The heart is the muscle that pumps blood. It ends with E-A-R-T."},
  {"questionText":"Which is the CORRECT spelling of the pair of organs used for breathing?","options":["A) loungs","B) lungss","C) longs","D) lungs"],"correctAnswer":"D","topic":"Body Parts and Their Functions","subTopic":"correct-spelling","difficulty":"Advanced","explanation":"'Lungs' is the correct spelling - L-U-N-G-S. Lungs take in oxygen and release carbon dioxide. Just 5 letters."},
  {"questionText":"Which is the CORRECT spelling of the transparent protective front surface of the eye?","options":["A) corneia","B) cornear","C) cornia","D) cornea"],"correctAnswer":"D","topic":"Body Parts and Their Functions","subTopic":"correct-spelling","difficulty":"Advanced","explanation":"'Cornea' is the correct spelling - C-O-R-N-E-A. The cornea is the clear dome-shaped front of the eye. It ends with E-A."},
  {"questionText":"Which is the CORRECT spelling of the longest bone in the human body?","options":["A) femor","B) feemur","C) femmur","D) femur"],"correctAnswer":"D","topic":"Body Parts and Their Functions","subTopic":"correct-spelling","difficulty":"Advanced","explanation":"'Femur' is the correct spelling - F-E-M-U-R. The femur is the thigh bone, the longest in the body. It ends with UR."},
  {"questionText":"Which is the CORRECT spelling of the organ that controls the whole nervous system?","options":["A) brainn","B) brean","C) brane","D) brain"],"correctAnswer":"D","topic":"Body Parts and Their Functions","subTopic":"correct-spelling","difficulty":"Advanced","explanation":"'Brain' is the correct spelling - B-R-A-I-N. The brain is the control centre of the body. It ends with AIN."},
  {"questionText":"One of these body parts is spelled INCORRECTLY. Which one?","options":["A) pupil","B) iris","C) earlob","D) heart"],"correctAnswer":"C","topic":"Body Parts and Their Functions","subTopic":"identify-misspelling","difficulty":"Advanced","explanation":"'Earlob' is spelled incorrectly. The correct spelling is 'earlobe' - E-A-R-L-O-B-E. It must end with E. Pupil, iris, and heart are correct."},
  {"questionText":"Which is the CORRECT spelling of the organ that filters blood and produces bile?","options":["A) livver","B) livar","C) liver","D) livur"],"correctAnswer":"C","topic":"Body Parts and Their Functions","subTopic":"correct-spelling","difficulty":"Olympiad","explanation":"'Liver' is the correct spelling - L-I-V-E-R. The liver filters blood and produces bile. It ends with ER."},
  {"questionText":"Which is the CORRECT spelling of the organs that filter waste products from blood?","options":["A) kideneys","B) kidnies","C) kidkneys","D) kidneys"],"correctAnswer":"D","topic":"Body Parts and Their Functions","subTopic":"correct-spelling","difficulty":"Olympiad","explanation":"'Kidneys' is the correct spelling - K-I-D-N-E-Y-S. The kidneys filter blood and produce urine. It ends with EYS."},
  {"questionText":"Which is the CORRECT spelling of the strong fibrous tissue that connects bones at joints?","options":["A) ligamant","B) liggament","C) ligament","D) ligument"],"correctAnswer":"C","topic":"Body Parts and Their Functions","subTopic":"correct-spelling","difficulty":"Olympiad","explanation":"'Ligament' is the correct spelling - L-I-G-A-M-E-N-T. Ligaments connect bones together. It ends with MENT."},
  {"questionText":"Which is the CORRECT spelling of the fibrous tissue that connects muscle to bone?","options":["A) tendan","B) tenddon","C) tenndon","D) tendon"],"correctAnswer":"D","topic":"Body Parts and Their Functions","subTopic":"correct-spelling","difficulty":"Olympiad","explanation":"'Tendon' is the correct spelling - T-E-N-D-O-N. Tendons attach muscles to bones. It ends with ON."},
  {"questionText":"Which is the CORRECT spelling of the smooth, rubbery tissue that cushions joints?","options":["A) cartillage","B) cattilage","C) cartalige","D) cartilage"],"correctAnswer":"D","topic":"Body Parts and Their Functions","subTopic":"correct-spelling","difficulty":"Olympiad","explanation":"'Cartilage' is the correct spelling - C-A-R-T-I-L-A-G-E. Cartilage reduces friction at joints. It ends with AGE."},
  {"questionText":"Which is the CORRECT spelling of the part of the brain at the back that controls balance?","options":["A) cerebelum","B) cerebellem","C) cerebellum","D) cerrabellum"],"correctAnswer":"C","topic":"Body Parts and Their Functions","subTopic":"correct-spelling","difficulty":"Olympiad","explanation":"'Cerebellum' is the correct spelling - C-E-R-E-B-E-L-L-U-M. The cerebellum controls balance and coordination. It has double L."},
  {"questionText":"One of these Olympiad body part words is spelled INCORRECTLY. Which one?","options":["A) liver","B) ligament","C) tendon","D) cerebelum"],"correctAnswer":"D","topic":"Body Parts and Their Functions","subTopic":"identify-misspelling","difficulty":"Olympiad","explanation":"'Cerebelum' is spelled incorrectly. The correct spelling is 'cerebellum' - C-E-R-E-B-E-L-L-U-M. It needs double L. Liver, ligament, and tendon are correct."}
]
'@

$newContent = $trimmed + $extra
[System.IO.File]::WriteAllText($f, $newContent, [System.Text.Encoding]::UTF8)

# Validate
$null = [System.IO.File]::ReadAllText($f, [System.Text.Encoding]::UTF8) | ConvertFrom-Json
$v = [regex]::Matches([System.IO.File]::ReadAllText($f, [System.Text.Encoding]::UTF8), '"questionText"').Count
Write-Host "body_parts now has: $v questions (valid JSON)"
